// =====================================================================
//  COMPSYS 303 - DE2-115 top level for the Lab 1 Nios II system
//  (replaces the Lab 1 schematic lab1.bdf; same pin names, same wiring)
//
//  Instantiates nios2_system (generated by Platform Designer from
//  nios2_system.qsys) and connects every exported conduit to the board
//  pins named in DE2_115_pin_assignments.csv.
//
//  If Quartus reports an unknown port, compare the port names below with
//  nios2_system/nios2_system_inst.v (generated next to the .qsys) - that
//  file is the authoritative instantiation template.
//
//  AI Use Declaration: written with the assistance of a generative AI tool
//  (Claude, Anthropic), reviewed and compiled by Harold and Lucas.
// =====================================================================
module traffic_top (
    input         CLOCK_50,
    input  [3:0]  KEY,          // KEY3 = system reset, KEY2..0 = keys PIO
    input  [17:0] SW,

    output [17:0] LEDR,
    output [8:0]  LEDG,

    input         UART_RXD,
    output        UART_TXD,

    output        LCD_EN,
    output        LCD_RS,
    output        LCD_RW,
    inout  [7:0]  LCD_DATA,
    output        LCD_ON,
    output        LCD_BLON,

    output        DRAM_CLK,
    output [12:0] DRAM_ADDR,
    output [1:0]  DRAM_BA,
    output        DRAM_CAS_N,
    output        DRAM_CKE,
    output        DRAM_CS_N,
    inout  [31:0] DRAM_DQ,
    output [3:0]  DRAM_DQM,
    output        DRAM_RAS_N,
    output        DRAM_WE_N
);

    // The SDRAM controller is configured 16 bits wide with 12 address bits
    // (as in Lab 1), so only the lower half of the 32-bit DE2-115 SDRAM is used.
    assign DRAM_ADDR[12]  = 1'b0;
    assign DRAM_DQM[3:2]  = 2'b11;      // upper 16 data bits masked
    assign DRAM_DQ[31:16] = 16'bz;      // and not driven

    assign LCD_ON   = 1'b1;             // LCD power and backlight always on (Lab 1: vcc)
    assign LCD_BLON = 1'b1;

    nios2_system u0 (
        .clk_clk                               (CLOCK_50),
        .reset_reset_n                         (KEY[3]),

        .keys_external_connection_export       (KEY[2:0]),
        .switches_external_connection_export   (SW),
        .leds_red_external_connection_export   (LEDR),
        .leds_green_external_connection_export (LEDG),

        .uart_external_connection_rxd          (UART_RXD),
        .uart_external_connection_txd          (UART_TXD),

        .lcd_external_E                        (LCD_EN),
        .lcd_external_RS                       (LCD_RS),
        .lcd_external_RW                       (LCD_RW),
        .lcd_external_data                     (LCD_DATA),

        .sdram_pll_sdram_clk_clk               (DRAM_CLK),
        .sdram_wire_addr                       (DRAM_ADDR[11:0]),
        .sdram_wire_ba                         (DRAM_BA),
        .sdram_wire_cas_n                      (DRAM_CAS_N),
        .sdram_wire_cke                        (DRAM_CKE),
        .sdram_wire_cs_n                       (DRAM_CS_N),
        .sdram_wire_dq                         (DRAM_DQ[15:0]),
        .sdram_wire_dqm                        (DRAM_DQM[1:0]),
        .sdram_wire_ras_n                      (DRAM_RAS_N),
        .sdram_wire_we_n                       (DRAM_WE_N)
    );

endmodule
